const http = require('http');
const fs = require('fs');
const path = require('path');

const url = 'http://127.0.0.1:65164/status';
const outDir = path.join(__dirname, 'results');
const outFile = path.join(outDir, 'status.json');

http.get(url, (res) => {
  let body = '';
  res.on('data', (chunk) => {
    body += chunk;
  });
  res.on('end', () => {
    if (res.statusCode !== 200) {
      console.error(`Unexpected HTTP status: ${res.statusCode}`);
      process.exit(1);
    }
    const data = JSON.parse(body);
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(outFile, JSON.stringify({ status: data.status }) + '\n');
    console.log(`Wrote status=${data.status} to ${outFile}`);
  });
}).on('error', (err) => {
  console.error(`Request failed: ${err.message}`);
  process.exit(1);
});

